function PatrolMainEventPanel:Awake()
    MazeMgr = import('Game.Maze.MazeMgr'):GetInstance()
    self.EventClosePanel = Events.AddListener(Constants.EventNames.PatrolEventClose, Bind(self, self.CloseEventPanel))
    self.EventEnterChoose = Events.AddListener(Constants.EventNames.PatrolEventChoose, Bind(self, self.EventChoose))

    --if isNull(self.mapEnv) then
    --    self.mapEnv = CfUtils.GetLuaScr(self.PatrolMapCellNode, "Game.UI.Patrol.PatrolMapCellNode")
    --end
    --KTool.GetOrAddComponent(self.BtnHide.gameObject, typeof(UIEventProxy)).onPointerClick = function()
    --    --KTool.SetActive(self.controller.transform, false)
    --    UIModule.BackDialog()
    --end
    SetButtonAction(self.FontStyleButton, function ()
        if (not isNull(self.data)) and (not isNull(self.key)) then
            --print("click-currentInfo-->>"..table.dump(MazeMgr.currentInfo, nil, 3))
            if MazeMgr.currentPos > 0 then
                self:BtnActionEnterChoose()
            else
                if MazeMgr.currentPos == 0 and self.data.type == 6 then
                    local recoveryNum = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting359, "BaseArgVo", 15).num)
                    self.co = cs_coroutine.start(function()
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                        GameUtils.Toast(localize("全体武装恢复血量_num_%", {_num_ = math.tointeger(recoveryNum * 100)}))
                    end)
                end
                MazeMgr:MazeMoveReq(self.key, function ()
                    self:BtnActionEnterChoose()
                end)
            end
        end
    end)
    local argument = self.controller.Argument
    if not isNull(argument.parameters) then
        --self.data = argument.parameters.data
        self.key = argument.parameters.key
        self.data = MazeMgr:GetCurrentChooseInfo(self.key)
        self:FreshBaseUI(self.data, self.key)
    end
end

