function PatrolMainEventPanel:FreshBaseUI(data, key)
    KTool.SetActive(self.controller.transform, true)
    self.data = data
    self.key = key
    --local mapData = {
    --    isMain = false,
    --    key = self.key,
    --}
    --self.mapEnv:FreshBaseUI(mapData)
    --local offset = self.
    --self.PatrolMapCellNode
    --这边的data.type是关卡点类型表中的id
    local typeData = CfUtils.GetCfVo(AutoIds.IdSetting351, "PatrolPointTypeVo",data.type)
    self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B3", typeData.butDesc)
    self.TxtTitle.text = typeData.name
    self.TxtNumber.text = string.format("<size=50>%d</size>/%d", MazeMgr.currentFloor, 45)
    if data.type == 1 or data.type == 2 or data.type == 3 then--1,2,3对应战斗事件
        KTool.SetActive(self.Fight, true)
        KTool.SetActive(self.UITeamMembersNodeFight, true)
        KTool.SetActive(self.UITeamMembersNode, false)
        --KTool.SetActive(self.TextArmNumber.transform, false)
        --KTool.SetActive(self.EventDesc, false)
        KTool.SetActive(self.RewardPreview, true)
        self.Text.Status = switchTextStatus.Fight
        --self.TextArmNumber.text = MazeMgr.monsterCombat
        KTool.SetActive(self.TxtStore, false)
        KTool.SetActive(self.StoreNode, false)

        local allLineVo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.data.questId)
        local teamMemberData = {}
        for k, v in pairs(allLineVo) do
            local monsterList = v.wave1NpcId
            for i, b in pairs(monsterList) do
                local monsterData = MazeMgr:GetMonstHpEnergyInfo(b)
                local monsterTypeData = CfUtils.GetCfVo(AutoIds.IdSetting39, "MonsterTypeVo", monsterData.id)
                if monsterTypeData.role > 0 then
                    local cardData = CardConfMgr:GetCardByRefId(monsterTypeData.mode)
                    monsterData["defaultSkin"] = monsterTypeData.skinId
                    monsterData["rare"] = cardData.rare
                else
                    monsterData["defaultSkin"] = monsterTypeData.skinId
                    monsterData["rare"] = monsterTypeData.monsterClass
                end
                table.insert(teamMemberData, monsterData)
            end
        end
        --printInfo("阵容---->>"..table.dump(allLineVo[1].wave1NpcId))
        --printInfo("队伍数据------->>"..table.dump(teamMemberData))
        local membersEnv = CfUtils.GetLuaScr(self.UITeamMembersNodeFight, "Game.UI.FightTeam.UITeamMembersNode.UITeamMembersNode")
        membersEnv:FillPatrolEventNode(teamMemberData)


        local rewardData = self:GetRewardData() --RewardConfMgr:GetTeamShowRewardData(data.questId)

        --printInfo("奖励预览------->>"..table.dump(rewardData))

        --local rewardEnv = CfUtils.GetLuaScr(self.RewardsNode, "Game.UI.FightReady.UIFightReardsNode.UIFightReardsNode")
        --rewardEnv:Refersh(rewardData, 0.6, true)
        local rewardEnv = CfUtils.GetLuaScr(self.RewardsNode, "Game.Behaviours.CommonGoodsList")
        rewardEnv:FreshBaseUI(rewardData)
        self.enterFunc = function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self.data.questId, point = data}}, {
                {id = Constants.UITypeIds.PatrolMainDialog},
            })
        end

    elseif data.type == 4 or data.type == 5 then--4,5对应商店
        KTool.SetActive(self.Fight, false)
        --KTool.SetActive(self.TextArmNumber.transform, false)
        --KTool.SetActive(self.EventDesc, true)
        KTool.SetActive(self.RewardPreview, false)
        KTool.SetActive(self.TxtStore, true)
        KTool.SetActive(self.StoreNode, true)

        local title
        --local desc
        if data.type == 4 then
            CfUtils.SetUISwitchImage(self.ImgRole, 1)
            title = localize("只有在夜晚出现的神秘商店，会出售珍稀商品。")
        else
            CfUtils.SetUISwitchImage(self.ImgRole, 2)
            title = localize("在新海市各处隐蔽设立的暴风眼特别调查署补给点。")
        end
        self.TxtStore.text = title
        --self.TextDesc.text = desc
        self.enterFunc = function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.PatrolStoreEventDialog, parameters = {data = self.data}}, {
                --{id = Constants.UITypeIds.ForgingDialog},
                --{id = Constants.UITypeIds.ForgingChallengePopup},
            })
        end
    elseif data.type == 6 then--6对应剧情
        KTool.SetActive(self.Fight, false)
        KTool.SetActive(self.TxtStore, true)
        KTool.SetActive(self.RewardPreview, false)
        KTool.SetActive(self.StoreNode, false)

        --KTool.SetActive(self.TextArmNumber.transform, false)
        --KTool.SetActive(self.EventDesc, true)
        --KTool.SetActive(self.TextDesc.transform, false)
        local storyData = CfUtils.GetCfVo(AutoIds.IdSetting356, "MazeStoryVo", data.eventId)
        local title = storyData.desc1
        --self.TextTitle.text = title
        self.TxtStore.text = title
        self.enterFunc = function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.PatrolPlotDialog, parameters = {data = self.data}}, {
                --{id = Constants.UITypeIds.ForgingDialog},
                --{id = Constants.UITypeIds.ForgingChallengePopup},
            })
        end
    elseif data.type == 7 then--7对应助战佣兵
        KTool.SetActive(self.Fight, true)
        KTool.SetActive(self.UITeamMembersNodeFight, false)
        KTool.SetActive(self.UITeamMembersNode, true)
        --KTool.SetActive(self.TextArmNumber.transform, false)
        --KTool.SetActive(self.EventDesc, false)
        KTool.SetActive(self.RewardPreview, false)
        KTool.SetActive(self.TxtStore, false)
        KTool.SetActive(self.StoreNode, false)

        self.Text.Status = switchTextStatus.Helper
        local assistantData = MazeMgr:GetAssistantInfo(key)
        local membersEnv = CfUtils.GetLuaScr(self.UITeamMembersNode, "Game.UI.FightTeam.UITeamMembersNode.UITeamMembersNode")
        membersEnv:FillPatrolEventNode(assistantData)
        self.enterFunc = function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.PatrolHelpSelectDialog, parameters = {data = self.data}}, {
                --{id = Constants.UITypeIds.ForgingDialog},
                --{id = Constants.UITypeIds.ForgingChallengePopup},
            })
        end
    end

end

--这边的type是关卡点类型表中的id
function PatrolMainEventPanel:GetRewardData()
    local difficultyVo = CfUtils.GetCfVo(AutoIds.IdSetting366, "PatrolDifficultyCoefficientVo", MazeMgr.mazeDifficultyId)
    local questRewardId
    if self.data.type == 1 then
        questRewardId = difficultyVo.lowRewardId
    elseif self.data.type == 2 then
        questRewardId = difficultyVo.midRewardId
    elseif self.data.type == 3 then
        questRewardId = difficultyVo.bossRewardId
    end
    if questRewardId == -1 then
        questRewardId = CfUtils.GetCfVo(AutoIds.IdSetting367, "PatrolFloorRewardsVo", checkString(MazeMgr.mazeDifficultyId)..checkString(MazeMgr.currentFloor)).rewardId
    end
    local rewardVo = CfUtils.GetCfVo(AutoIds.IdSetting752, "QuestRewardVo", questRewardId)
    local items = CfUtils.Split(rewardVo.showItem)
    local showItemTags = CfUtils.Split(rewardVo.showItemTag)
    local showItemNums = CfUtils.Split(rewardVo.showItemNum)
    local rewardData = {}
    if items and showItemTags and showItemNums then
        for i = 1, #items do
            local reward = {
                ["id"] = checkNumber(items[i]),
                ["num"] = checkNumber(showItemNums[i]),
                ["type"] = checkNumber(showItemTags[i]),
            }
            table.insert(rewardData, reward)
        end
    end
    return rewardData
end

---确认进入选择
function PatrolMainEventPanel:BtnActionEnterChoose()
    if type(self.enterFunc) == 'function' then
        self.enterFunc()
        self:CloseEventPanel()
    end
end

function PatrolMainEventPanel:CloseEventPanel()
    UIModule.CloseDialog(self.controller, true)
end

function PatrolMainEventPanel:OnFinalize()
    KCookie.Set("isPatrolEventPanelOpen", nil)
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.PatrolEventClose, self.EventClosePanel)
        Events.RemoveListener(Constants.EventNames.PatrolEventChoose, self.EventEnterChoose)
        Events.Broadcast(Constants.EventNames.PatrolEventChoose)
        MazeMgr = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return PatrolMainEventPanel